// A complete, runnable thermostat so you can see the returned String in action.
// The exercise's Thermostat.java is a fragment: it shows only the changed method.
public class ThermostatDemo {

    private double currentTemperature;
    private double targetTemperature;

    public ThermostatDemo(double currentTemperature, double targetTemperature) {
        this.currentTemperature = currentTemperature;
        this.targetTemperature = targetTemperature;
    }

    public String getStatus() {
        if (currentTemperature < targetTemperature) {
            return "HEATING";
        } else if (currentTemperature > targetTemperature) {
            return "COOLING";
        } else {
            return "IDLE";
        }
    }

    // The method from the exercise, returning a String instead of printing.
    public String printStatusToDisplay() {
        return "Thermostat status: " + getStatus();
    }

    public static void main(String[] args) {
        ThermostatDemo cold = new ThermostatDemo(18.0, 21.0);
        ThermostatDemo warm = new ThermostatDemo(23.5, 21.0);
        ThermostatDemo settled = new ThermostatDemo(21.0, 21.0);

        // The caller decides what to do with the returned text.
        System.out.println(cold.printStatusToDisplay());
        System.out.println(warm.printStatusToDisplay());
        System.out.println(settled.printStatusToDisplay());

        // Because a String comes back, it can be checked instead of just watched.
        String expected = "Thermostat status: HEATING";
        System.out.println("Matches expected? " + expected.equals(cold.printStatusToDisplay()));
    }
}

public class Thermostat {
    private int temperature;
    private boolean ecoMode;

    public Thermostat(int temperature, boolean ecoMode) {
        this.temperature = temperature;
        this.ecoMode = ecoMode;
    }

    public String getStatus() {
        int heatBelow = ecoMode ? 65 : 68;
        int coolAbove = ecoMode ? 78 : 75;

        if (temperature < heatBelow) {
            return "Heating";
        } else if (temperature > coolAbove) {
            return "Cooling";
        } else {
            return "Idle";
        }
    }

    public String printStatusToDisplay() {
        return "Thermostat status: " + getStatus();
    }
}

public class TemperatureSensorDemo {

    // A stand-in sensor. Real hardware would report a live reading here.
    static class FakeSensor implements TemperatureSensor {
        private final int[] readings = {68, 62, 55};
        private int index = 0;

        @Override
        public int getCurrentTemperature() {
            int reading = readings[index];
            index = (index + 1) % readings.length;
            return reading;
        }
    }

    public static void main(String[] args) {
        TemperatureSensor sensor = new FakeSensor();
        for (int i = 0; i < 3; i++) {
            System.out.println("Sensor reports: " + sensor.getCurrentTemperature() + "F");
        }
    }
}

