import java.util.List;
import java.util.PriorityQueue;

public class EnergyQueueDemo {
    public static void main(String[] args) {
        List<Song> playlist = new ArrayList<>();
        playlist.add(new Song("Bohemian Rhapsody", "Queen", "Rock", 7));
        playlist.add(new Song("Thunderstruck", "AC/DC", "Rock", 10));
        playlist.add(new Song("Clair de Lune", "Debussy", "Classical", 2));
        playlist.add(new Song("Billie Jean", "Michael Jackson", "Pop", 8));

        System.out.println("\n--- Priority Playlist (Songs by Energy, High \u2192 Low) ---");
        PriorityQueue<Song> energyQueue = new PriorityQueue<>(
                Comparator.comparingInt(Song::getEnergyLevel).reversed());
        energyQueue.addAll(playlist);

        System.out.println("Processing by energy with poll():");
        while (!energyQueue.isEmpty()) {
            Song nextSong = energyQueue.poll();
            System.out.println("Playing: " + nextSong);
        }
    }
}

