// Driver for the exercise. The printed listing leaves the product list as a
// comment, so this file supplies a small list of items and runs the same two
// stream pipelines against it.
public class MarketDemo {

    static class Item {
        private final String name;
        private final double price;
        private final boolean organic;

        Item(String name, double price, boolean organic) {
            this.name = name;
            this.price = price;
            this.organic = organic;
        }

        public String getName() { return name; }
        public double getPrice() { return price; }
        public boolean isOrganic() { return organic; }
    }

    public static void main(String[] args) {
        List<Item> products = List.of(
                new Item("Heirloom Tomatoes", 4.50, true),
                new Item("Sweet Corn", 3.25, false),
                new Item("Goat Cheese", 8.00, true),
                new Item("Apple Cider", 6.75, false),
                new Item("Kale", 2.95, true));

        double totalSum = getTotalPriceSum(products);
        System.out.println("\nTotal inventory value: $" + String.format("%.2f", totalSum));

        double avgOrganic = getAverageOrganicPrice(products);
        System.out.println("Average price (organic items): $" + String.format("%.2f", avgOrganic));
    }

    // 4) Sum all prices using mapToDouble
    public static double getTotalPriceSum(List<Item> products) {
        return products.stream()
                .mapToDouble(Item::getPrice)
                .sum();
    }

    // 5) Average price of organic items
    public static double getAverageOrganicPrice(List<Item> products) {
        return products.stream()
                .filter(Item::isOrganic)
                .mapToDouble(Item::getPrice)
                .average()
                .orElse(0.0);
    }
}

import java.util.List;

public class WeatherApp {
    public static void main(String[] args) {
        List<WeatherEntry> week = List.of(
                new WeatherEntry("2026-07-01", 22.5, "Sunny"),
                new WeatherEntry("2026-07-02", 19.0, "Rainy"),
                new WeatherEntry("2026-07-03", 25.5, "Sunny"),
                new WeatherEntry("2026-07-04", 17.5, "Cloudy"),
                new WeatherEntry("2026-07-05", 16.0, "Rainy"),
                new WeatherEntry("2026-07-06", 28.0, "Sunny"),
                new WeatherEntry("2026-07-07", 21.0, "Cloudy"),
                new WeatherEntry("2026-07-08", 14.5, "Rainy"),
                new WeatherEntry("2026-07-09", 30.5, "Sunny"),
                new WeatherEntry("2026-07-10", 18.5, "Windy"));

        System.out.println("Rainy days:");
        week.stream()
            .filter(entry -> entry.getCondition().equals("Rainy"))
            .forEach(System.out::println);

        System.out.println();
        System.out.println("Temperatures in Fahrenheit:");
        week.stream()
            .map(entry -> entry.getCelsius() * 9 / 5 + 32)
            .forEach(f -> System.out.printf("%.1f F%n", f));

        System.out.println();
        double average = week.stream()
                             .limit(7)
                             .mapToDouble(WeatherEntry::getCelsius)
                             .average()
                             .orElse(0.0);
        System.out.printf("Average for the first week: %.2f C%n", average);
    }
}

